import { Router } from "express";
import { z } from "zod";
import { countOpenIncidents, findHome, listHomes } from "../store.ts";

export const homesRouter = Router();

/** GET /api/homes — every home, with how many incidents are currently open. */
homesRouter.get("/", (_req, res) => {
  res.json({
    homes: listHomes().map((home) => ({ ...home, openIncidents: countOpenIncidents(home.id) })),
  });
});

const homeParams = z.object({ homeId: z.string().min(1) });

/** GET /api/homes/:homeId — one home. */
homesRouter.get("/:homeId", (req, res) => {
  const params = homeParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "invalid_params", detail: params.error.issues });
    return;
  }

  const home = findHome(params.data.homeId);
  if (!home) {
    res.status(404).json({ error: "home_not_found", homeId: params.data.homeId });
    return;
  }
  res.json({ home: { ...home, openIncidents: countOpenIncidents(home.id) } });
});

import { Router } from "express";
import { z } from "zod";
import { findHome, listIncidents } from "../store.ts";

export const incidentsRouter = Router({ mergeParams: true });

const incidentParams = z.object({ homeId: z.string().min(1) });

const incidentQuery = z.object({
  state: z.enum(["open", "resolved"]).optional(),
});

/** GET /api/homes/:homeId/incidents — a home's incidents, newest first. */
incidentsRouter.get("/", (req, res) => {
  const params = incidentParams.safeParse(req.params);
  if (!params.success) {
    res.status(400).json({ error: "invalid_params", detail: params.error.issues });
    return;
  }

  const query = incidentQuery.safeParse(req.query);
  if (!query.success) {
    res.status(400).json({ error: "invalid_query", detail: query.error.issues });
    return;
  }

  const { homeId } = params.data;
  if (!findHome(homeId)) {
    res.status(404).json({ error: "home_not_found", homeId });
    return;
  }

  res.json({ incidents: listIncidents(homeId, query.data.state) });
});

/**
 * The data layer. Reads the fixture once at startup and keeps it in memory, so the service has
 * no database to set up. Writes stay in memory and are lost on restart.
 */
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

export type Home = {
  id: string;
  name: string;
  address: string;
  timezone: string;
  devices: number;
};

export type IncidentKind = "noise" | "occupancy" | "offline";
export type IncidentStatus = "open" | "resolved";

export type Incident = {
  id: string;
  homeId: string;
  kind: IncidentKind;
  startedAt: string;
  endedAt: string | null;
  peakDb: number | null;
  status: IncidentStatus;
};

type Fixture = { homes: Home[]; incidents: Incident[] };

const dataFile = join(dirname(fileURLToPath(import.meta.url)), "../data/homes.json");
const fixture: Fixture = JSON.parse(readFileSync(dataFile, "utf8"));

const homes = [...fixture.homes];
const incidents = [...fixture.incidents];

export const listHomes = (): Home[] => [...homes];

export const findHome = (id: string): Home | undefined => homes.find((home) => home.id === id);

export function listIncidents(homeId: string, status?: IncidentStatus): Incident[] {
  return incidents
    .filter((incident) => incident.homeId === homeId)
    .filter((incident) => (status ? incident.status === status : true))
    .sort((a, b) => b.startedAt.localeCompare(a.startedAt));
}

export const countOpenIncidents = (homeId: string): number =>
  incidents.filter((incident) => incident.homeId === homeId && incident.status === "open").length;

import express from "express";
import { homesRouter } from "./routes/homes.ts";
import { incidentsRouter } from "./routes/incidents.ts";

export function createApp() {
  const app = express();
  app.use(express.json());

  // The dev web app runs on another port.
  app.use((_req, res, next) => {
    res.setHeader("access-control-allow-origin", "*");
    res.setHeader("access-control-allow-headers", "content-type");
    next();
  });

  app.get("/api/health", (_req, res) => res.json({ ok: true }));
  app.use("/api/homes/:homeId/incidents", incidentsRouter);
  app.use("/api/homes", homesRouter);

  app.use((_req, res) => res.status(404).json({ error: "not_found" }));
  return app;
}

/** Everything this app knows about the backend. */

const BASE = import.meta.env.VITE_API_URL ?? "http://localhost:3001";

export type Home = {
  id: string;
  name: string;
  address: string;
  timezone: string;
  devices: number;
  openIncidents: number;
};

export type IncidentKind = "noise" | "occupancy" | "offline";
export type IncidentStatus = "open" | "resolved";

export type Incident = {
  id: string;
  homeId: string;
  kind: IncidentKind;
  startedAt: string;
  endedAt: string | null;
  peakDb: number | null;
  status: IncidentStatus;
};

async function get<T>(path: string): Promise<T> {
  const res = await fetch(`${BASE}${path}`);
  if (!res.ok) throw new Error(`${path} returned ${res.status}`);
  // The response shape is trusted here, not validated. The backend's own tests are what hold it.
  return res.json() as Promise<T>;
}

export async function getHomes(): Promise<Home[]> {
  const body = await get<{ homes: Home[] }>("/api/homes");
  return body.homes;
}

export async function getIncidents(homeId: string, status?: IncidentStatus): Promise<Incident[]> {
  const query = status ? `?status=${status}` : "";
  const body = await get<{ incidents: Incident[] }>(`/api/homes/${homeId}/incidents${query}`);
  return body.incidents;
}

import { useEffect, useState } from "react";
import type { Home, Incident } from "../api.ts";
import { getIncidents } from "../api.ts";
import { formatPeak, formatStarted, kindLabel } from "../format.ts";

export function IncidentList({ home }: { home: Home }) {
  const [incidents, setIncidents] = useState<Incident[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setIncidents(null);
    setError(null);
    let current = true;
    getIncidents(home.id, "open").then(
      (rows) => { if (current) setIncidents(rows); },
      (reason: unknown) => { if (current) setError(String(reason)); },
    );
    return () => {
      current = false;
    };
  }, [home.id]);

  return (
    <section className="panel" aria-label={`Incidents for ${home.name}`}>
      <h2>{home.name}</h2>
      <p className="muted">
        {home.devices} device{home.devices === 1 ? "" : "s"} · {home.timezone}
      </p>

      {error && <p className="error">Could not load incidents: {error}</p>}
      {!incidents && !error && <p className="muted">Loading…</p>}
      {incidents?.length === 0 && <p className="muted">No open incidents.</p>}

      {incidents && incidents.length > 0 && (
        <ul className="incidents">
          {incidents.map((incident) => (
            <li key={incident.id} className={`incident ${incident.kind}`}>
              <span className="incident-kind">{kindLabel[incident.kind]}</span>
              <span className="incident-when">{formatStarted(incident.startedAt)}</span>
              <span className="incident-peak">{formatPeak(incident.peakDb)}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

import { useEffect, useState } from "react";
import type { Home } from "./api.ts";
import { getHomes } from "./api.ts";
import { HomeList } from "./components/HomeList.tsx";
import { IncidentList } from "./components/IncidentList.tsx";

export function App() {
  const [homes, setHomes] = useState<Home[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  useEffect(() => {
    getHomes().then(setHomes, (reason: unknown) => setError(String(reason)));
  }, []);

  const selected = homes?.find((home) => home.id === selectedId) ?? null;

  return (
    <div className="app">
      <header>
        <h1>Property monitor</h1>
      </header>

      {error && <p className="error">Could not load homes: {error}</p>}
      {!homes && !error && <p className="muted">Loading…</p>}

      {homes && (
        <main>
          <HomeList homes={homes} selectedId={selectedId} onSelect={setSelectedId} />
          {selected ? (
            <IncidentList home={selected} />
          ) : (
            <section className="panel">
              <p className="muted">Pick a home to see its incidents.</p>
            </section>
          )}
        </main>
      )}
    </div>
  );
}

import type { Home } from "../api.ts";

type Props = {
  homes: Home[];
  selectedId: string | null;
  onSelect: (id: string) => void;
